type Row = Record<string, unknown>;
const messageOf = (error: unknown) => error instanceof Error ? error.message : 'Unable to complete the request. Please try again.';
const request = (method: string, data?: unknown): RequestInit => ({ method, ...(data === undefined ? {} : { body: JSON.stringify(data) }) });
const columnLabels: Record<string, string> = { created_at: 'Date', occurred_at: 'Date', replied_at: 'Replied', read_at: 'Read', livemode: 'Payment mode', resource_type: 'For', order_number: 'Order', total_centavos: 'Total', full_name: 'Name', is_published: 'Published', is_active: 'Active', is_approved: 'Approved', access: 'Account type', coverage_status: 'Coverage', pet_details: 'Pet', preferred_schedule: 'Preferred schedule', stock_quantity: 'Stock', event_count: 'Events', role_name: 'Role' };
const columnLabel = (key: string) => columnLabels[key] ?? sentenceCase(key.replace('_centavos', '').replace(/_id$/, ''));
const sentenceCase = (text: string) => { const words = text.replaceAll('_', ' '); return words.charAt(0).toUpperCase() + words.slice(1); };
const titleCase = (text: string) => text.replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
const date = (value: unknown) => typeof value === 'string' && !Number.isNaN(Date.parse(value)) ? new Intl.DateTimeFormat('en-PH', { dateStyle: 'medium', timeZone: 'Asia/Manila' }).format(new Date(value)) : '—';
function valueText(value: unknown): string { if (value == null || value === '') return '—'; if (typeof value === 'boolean') return value ? 'Yes' : 'No'; if (Array.isArray(value)) return value.map(valueText).join(', '); if (typeof value === 'object') return JSON.stringify(value, null, 2); return String(value); }
function Notice({ error, success }: { error?: string; success?: string }) { return <>{error && <div className="notice error" role="alert">{error}</div>}{success && <div className="notice success" role="status"><Check size={17} />{success}</div>}</>; }
function QueryState({ loading, error }: { loading: boolean; error: unknown }) { const cache = useQueryClient(); return loading ? <div className="dashboard-skeleton" aria-label="Loading records"><div /><div /><div /></div> : error ? <div className="notice error" role="alert">{messageOf(error)} <button className="text-button" onClick={() => void cache.refetchQueries({type: 'active'})}>Retry</button></div> : null; }

