const workspaceGroups: Record<string, string> = {
  security: 'Security & access', security_alerts: 'Security & access', security_events: 'Security & access', critical_approvals: 'Security & access',
  products: 'Store', categories: 'Store', orders: 'Store', payments: 'Store', refunds: 'Store', reviews: 'Store',
  pets: 'Animals & adoption', health: 'Animals & adoption', adoptions: 'Animals & adoption',
  rescue: 'Rescue & transport', transport: 'Rescue & transport', alternatives: 'Rescue & transport', zones: 'Rescue & transport', vehicles: 'Rescue & transport', drivers: 'Rescue & transport',
  donations: 'Community & finance', volunteers: 'Community & finance', expenses: 'Community & finance', contact_messages: 'Community & finance',
  users: 'Security & access', audit_logs: 'Security & access', shelter_location: 'Settings',
};
const personalTabs = ['profile', 'settings', 'notifications'];
const volunteerTab = { key: 'volunteer', label: 'Volunteer tasks', icon: Users };
/** Customers get the full dashboard. Shelter personnel work in the workspace, so here they only keep their personal settings. */
function accountTabsFor(roles: string[]) {
  if (isOperational(roles)) return accountTabs.filter((item) => personalTabs.includes(item.key));
  if (!roles.includes('volunteer')) return accountTabs;
  const index = accountTabs.findIndex((item) => item.key === 'donations') + 1;
  return [...accountTabs.slice(0, index), volunteerTab, ...accountTabs.slice(index)];
}

export function DashboardPage() {
  const { user, profile, roles, permissions, loading, rolesLoading, rolesError, signOut } = useAuth(); const { tab } = useParams(); const navigate = useNavigate(); const [error, setError] = useState('');
  if (rolesError) return <div className="page container"><QueryState loading={false} error={rolesError}/></div>;
  if (loading || rolesLoading) return <div className="page container"><QueryState loading error={null} /></div>;
  if (!user) return <div className="page"><div className="container card account-gate"><UserRound size={36} /><h1>Your caring corner of the world.</h1><p>Sign in to see your orders, adoption applications, reports, and shelter updates.</p><Link className="btn btn-primary" to="/auth/login?next=/account">Sign in to your account<ArrowRight size={17} /></Link></div></div>;
  const operational = isOperational(roles); const tabs = accountTabsFor(roles); const hasWorkspace = workspaceSections(roles, permissions).length > 0;
  if (!tab) return <Navigate to={homePath(roles, permissions)} replace />;
  if (operational && !personalTabs.includes(tab!)) return <Navigate to="/account/profile" replace />;
  async function logout() { try { await signOut(); navigate('/'); } catch (failure) { setError(messageOf(failure)); } }
  const current = tabs.find((item) => item.key === (tab === 'adoptions' ? 'applications' : tab)) || tabs.find(item => item.key === 'overview') || tabs[0];
  const name = profile?.full_name || '';
  const menu: NavItem[] = [
    ...(operational ? workspaceTabsFor(roles, permissions).map(item => ({ ...item, to: `/admin/${item.key}`, group: workspaceGroups[item.key] })) : []),
    ...(roles.includes('super_administrator') ? [{ key: 'operations', label: 'IT Operations', icon: Settings, to: '/admin/operations' }] : []),
    ...tabs.map((item) => ({ ...item, to: `/account/${item.key}`, group: accountGroups[item.key] })),
    ...(!operational && hasWorkspace ? [{ key: 'assignments', label: 'Rescue assignments', icon: ShieldCheck, to: '/admin', group: accountGroups.assignments }] : []),
  ];
  return <div className="page"><div className="container dashboard-layout"><WorkspaceSidebar><div className="account-identity"><span>{String(name || user.email || 'P').charAt(0).toUpperCase()}</span><div><strong>{name || 'Welcome back'}</strong><small>{user.email}</small></div></div>{(operational || roles.includes('volunteer')) && <span className="badge role-badge">{roleTitle(roles)}</span>}<GroupedNav label="Account navigation" current={current.key} items={menu} /><button className="text-button" onClick={logout}><LogOut size={16} />Sign out</button></WorkspaceSidebar><section className="dashboard-main"><div className="feature-toolbar"><div><span className="eyebrow">{operational ? roleTitle(roles).toUpperCase() : 'YOUR PAWSCONNECT'}</span><h1>{current.label}</h1></div>{operational ? <Link className="btn btn-secondary" to="/admin">Open workspace<ArrowRight size={16} /></Link> : <Link className="btn btn-secondary" to="/shop">Keep exploring<ArrowRight size={16} /></Link>}</div><Notice error={error} />{current.key === 'overview' ? <AccountOverview /> : current.key === 'addresses' ? <Addresses /> : current.key === 'profile' ? <Profile /> : current.key === 'settings' ? <><AccountSettings /><RestartTourButton /></> : current.key === 'volunteer' ? <VolunteerTasks /> : <AccountRecords tab={current.key} />}</section></div></div>;
}

type VolunteerTask = { id: string; title: string; description?: string | null; status: string; scheduled_at?: string | null };
function VolunteerTasks() {
  const cache = useQueryClient(); const [error, setError] = useState('');
  const mine = useQuery({ queryKey: ['volunteer', 'mine'], queryFn: () => api<{ status: string; tasks: VolunteerTask[] } | null>('/volunteers/mine') });
  async function update(id: string, status: string) { setError(''); try { await api(`/volunteers/tasks/${id}`, request('PATCH', { status })); await cache.invalidateQueries({ queryKey: ['volunteer', 'mine'] }); } catch (failure) { setError(messageOf(failure)); } }
  if (mine.isLoading || mine.error) return <QueryState loading={mine.isLoading} error={mine.error} />;
  if (!mine.data) return <div className="card empty-state"><Users size={34} /><h3>No volunteer application on file.</h3><p>Tell the shelter how you would like to help and when you are available.</p><Link className="btn btn-primary" to="/volunteer">Apply to volunteer<ArrowRight size={16} /></Link></div>;
  const tasks = mine.data.tasks || [];
  return <><div className="notice">Volunteer status: <strong>{titleCase(mine.data.status)}</strong>. Tasks are assigned by shelter staff.</div><Notice error={error} />{!tasks.length ? <div className="card empty-state"><ClipboardList size={34} /><h3>No tasks assigned yet.</h3><p>When staff assign you an activity it will appear here.</p></div> : <div className="address-grid">{tasks.map((task) => <article className="card address-card" key={task.id}><div className="feature-toolbar"><h3>{task.title}</h3><span className={`badge status-${task.status}`}>{titleCase(task.status)}</span></div>{task.description && <p>{task.description}</p>}<p className="muted small">{task.scheduled_at ? `Scheduled ${date(task.scheduled_at)}` : 'No date set'}</p><div className="table-actions">{task.status === 'assigned' && <button className="text-button" onClick={() => update(task.id, 'in_progress')}>Start task</button>}{['assigned', 'in_progress'].includes(task.status) && <button className="text-button" onClick={() => update(task.id, 'completed')}><Check size={15} />Mark complete</button>}</div></article>)}</div>}</>;
}

function AccountOverview() {
  const { user, profile } = useAuth();
  const counts = useQuery({ queryKey: ['account-overview', user?.id], queryFn: ({signal}) => api<Record<string, number>>('/account/summary',{signal}) });
  return <><div className="account-welcome"><div><span className="eyebrow">A GOOD DAY TO DO SOME GOOD</span><h2>Hello, {String(profile?.full_name || 'friend').split(' ')[0]}.</h2><p>Your orders, your companions, your little acts of kindness. All together here.</p><Link className="btn btn-primary" to="/match">Find my paw-fect match<SparkleIcon /></Link></div><PawPrint className="welcome-paw" size={160} /></div><QueryState loading={counts.isLoading} error={counts.error} />{counts.data && <div className="stat-grid">{[{ label: 'Orders placed', key: 'orders', href: 'orders' }, { label: 'Adoption applications', key: 'applications', href: 'applications' }, { label: 'Rescue reports', key: 'reports', href: 'reports' }, { label: 'Unread updates', key: 'updates', href: 'notifications' }].map((item) => <Link className="card stat-card" to={`/account/${item.href}`} key={item.key}><span>{item.label}</span><strong>{counts.data[item.key as keyof typeof counts.data]}</strong><small>View details<ArrowRight size={13} /></small></Link>)}</div>}<h2 className="section-heading">A little inspiration for today</h2><div className="account-quick-links"><Link className="card" to="/shop"><ShoppingBag /><h3>Restock their favorites</h3><p>Everyday essentials for happy, healthy pets.</p><ArrowRight size={18} /></Link><Link className="card" to="/volunteer"><Users /><h3>Share a little time</h3><p>Find a way to lend your skills to the shelter.</p><ArrowRight size={18} /></Link><Link className="card" to="/donate"><Heart /><h3>Make a little difference</h3><p>Support daily care and second chances.</p><ArrowRight size={18} /></Link></div></>;
}
function SparkleIcon() { return <PawPrint size={16} />; }

function RecordDetail({ record, onClose }: { record: Row; onClose: () => void }) {
  return <RecordDialog onClose={onClose} label="Record details"><section className="card record-modal" role="dialog" aria-modal="true" aria-label="Record details" onClick={(event) => event.stopPropagation()}><div className="feature-toolbar"><h2>Record details</h2><button className="icon-button" onClick={onClose} aria-label="Close details"><X /></button></div><Attachments row={record}/><dl className="record-details">{Object.entries(record).filter(([key]) => !['user_id', 'provider_payload'].includes(key)).map(([key, value]) => <div key={key}><dt>{titleCase(key)}</dt><dd>{key.endsWith('_centavos') ? money(Number(value)) : key.endsWith('_at') ? date(value) : <span className={typeof value === 'object' ? 'record-json' : ''}>{valueText(value)}</span>}</dd></div>)}</dl></section></RecordDialog>;
}
function AccountRecords({ tab }: { tab: string }) {
  const confirm=useConfirmation();
  const cache = useQueryClient(); const [selected, setSelected] = useState<Row | null>(null); const [error, setError] = useState(''); const [page, setPage] = useState(1); const [query, setQuery] = useState('');
  const { user } = useAuth(); const [busy, setBusy] = useState(false);
  const settledQuery=useDebouncedValue(query);
  const records = useQuery({ queryKey: ['account', tab, user?.id, page, settledQuery], queryFn: ({signal}) => apiEnvelope<Row[]>(`/account/records/${tab}?page=${page}&limit=10&q=${encodeURIComponent(settledQuery)}`,{signal}) });
  useEffect(() => { setSelected(null); setPage(1); setQuery(''); setError(''); }, [tab]);
  async function details(row: Row) { setError(''); try { if (tab === 'orders') setSelected(await api(`/orders/${row.id}`)); else if (tab === 'transport') setSelected(await api(`/transport/requests/${row.id}`)); else setSelected(row); } catch (failure) { setError(messageOf(failure)); } }
  async function action(row: Row, name: string) { if(busy)return; setBusy(true); setError(''); try { if(name === 'favorite-remove') await api(`/favorite-pets/${row.pet_id}`, request('DELETE')); else if(name === 'confirm-quote') { if(!(await confirm('Accept the recorded transport quotation?')).confirmed) return; await api(`/transport/requests/${row.id}/confirm`,request('POST')); } else if(name === 'withdraw') { if(!(await confirm('Withdraw this adoption application?')).confirmed) return; await api(`/adoption-applications/${row.id}/withdraw`,request('POST')); } else if(name === 'refund') { const answer=await confirm({title:'Request a refund',resource:String(row.id),reason:true,confirmLabel:'Request refund'});if(!answer.confirmed)return;const reason=answer.reason; await api('/refund-requests',request('POST',{payment_id:row.id,reason})); } else if (name === 'read') await api(`/notifications/${row.id}`, request('PATCH', { read: true })); else if (name === 'remove') await api(`/wishlist/${row.product_id}`, request('DELETE')); else if (name === 'pay') { const resourceType = tab === 'orders' ? 'order' : tab === 'transport' ? 'transport' : tab === 'applications' ? 'adoption' : 'donation'; const result = await api<{ checkout_url: string }>('/payments/create', request('POST', { resource_type: resourceType, resource_id: row.id })); if (!result.checkout_url) throw new Error('A checkout link is not available for this request.'); window.location.assign(result.checkout_url); } else if (name === 'cancel') { if (!(await confirm('Cancel this unpaid order and release its reserved stock?')).confirmed) return; await api(`/orders/${row.id}/cancel`, request('POST')); } await cache.invalidateQueries({queryKey:['account',tab]},{cancelRefetch:false}); } catch (failure) { setError(messageOf(failure)); } finally { setBusy(false); } }
  const rows = records.error ? [] : (records.data?.data || []);
  const visible = rows; const columns = accountColumns[tab] || ['id', 'status'];
  return <><div className="feature-toolbar"><label className="dashboard-search"><Search size={17} /><input placeholder={`Search ${tab}…`} value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }} /></label><span className="muted small">{rows.length} records</span></div><QueryState loading={records.isLoading} error={records.error} /><Notice error={error} />{!records.isLoading && !records.error && !rows.length && <div className="card empty-state"><Package size={34} /><h3>Nothing here just yet.</h3><p>Your {tab} will appear here when you get started.</p><Link className="btn btn-primary" to={tab === 'applications' ? '/adopt' : tab === 'reports' ? '/rescue' : tab === 'transport' ? '/transport' : tab === 'donations' ? '/donate' : '/shop'}>Explore PawsConnect<ArrowRight size={16} /></Link></div>}{visible.length > 0 && <div className="card table-wrap"><table className="record-table"><thead><tr>{columns.map((key) => <th key={key}>{columnLabel(key)}</th>)}<th>Actions</th></tr></thead><tbody>{visible.map((row, index) => <tr key={String(row.id || row.product_id || row.pet_id || index)}>{columns.map((key) => <td key={key} data-label={columnLabel(key)}>{cell(row, key)}</td>)}<td data-label="Actions"><div className="table-actions">{tab === 'favorites' ? <><Link to={`/adopt/${row.pet_id}`}>View pet</Link><button disabled={busy} className="text-button" onClick={() => action(row, 'favorite-remove')}>Remove</button></> : tab === 'wishlist' ? <><Link className="text-button" to={`/shop/${row.product_id}`}>View product</Link><button className="text-button" disabled={busy} onClick={() => action(row, 'remove')} aria-label="Remove from wishlist"><Trash2 size={15} /></button></> : <button className="text-button" disabled={busy} onClick={() => details(row)}>Details</button>}{tab === 'payments' && row.status === 'paid' && <button disabled={busy} className="text-button" onClick={() => action(row, 'refund')}>Request refund</button>}{tab === 'transport' && row.status === 'quoted' && <button disabled={busy} className="text-button" onClick={() => action(row, 'confirm-quote')}>Accept quote</button>}{tab === 'applications' && !['withdrawn','rejected','completed'].includes(String(row.status)) && <button disabled={busy} className="text-button" onClick={() => action(row, 'withdraw')}>Withdraw</button>}{tab === 'applications' && ['approved','reserved','awaiting_handover'].includes(String(row.status)) && Number(row.fee_centavos)>0 && !row.fee_paid_at && <button disabled={busy} className="text-button" onClick={() => action(row, 'pay')}>Pay adoption fee</button>}{tab === 'notifications' && !row.read_at && <button className="text-button" disabled={busy} onClick={() => action(row, 'read')}>Mark read</button>}{((tab === 'orders' && row.status === 'pending_payment') || (tab === 'donations' && row.status === 'pending' && row.donation_type === 'monetary') || (tab === 'transport' && row.status === 'confirmed')) && <button className="text-button" disabled={busy} onClick={() => action(row, 'pay')}>Pay securely</button>}{tab === 'orders' && row.status === 'pending_payment' && <button className="text-button" disabled={busy} onClick={() => action(row, 'cancel')}>Cancel</button>}</div></td></tr>)}</tbody></table></div>}{<Pagination page={page} hasNext={page * 10 < (records.data?.meta?.total || 0)} setPage={setPage} />}{selected && <RecordDetail record={selected} onClose={() => setSelected(null)} />}</>;
}
function Pagination({ page, hasNext, setPage }: { page: number; hasNext: boolean; setPage: (page: number) => void }) { return <div className="pagination"><button className="btn btn-secondary" disabled={page <= 1} onClick={() => setPage(page - 1)}><ChevronLeft size={16} />Previous</button><span>Page {page}</span><button className="btn btn-secondary" disabled={!hasNext} onClick={() => setPage(page + 1)}>Next<ChevronRight size={16} /></button></div>; }

function Profile() {
  const cache = useQueryClient(); const profile = useQuery({ queryKey: ['profile'], queryFn: ({signal}) => api<Row>('/profile',{signal}) }); const { user } = useAuth(); const [error, setError] = useState(''); const [success, setSuccess] = useState(''); const [busy, setBusy] = useState(false);
  async function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); setError(''); try { await api('/profile', request('PATCH', Object.fromEntries(new FormData(event.currentTarget)))); await cache.invalidateQueries({ queryKey: ['profile'] }); setSuccess('Your profile is updated.'); } catch (failure) { setError(messageOf(failure)); } finally { setBusy(false); } }
  return <><QueryState loading={profile.isLoading} error={profile.error} />{profile.data && <form className="card service-form" onSubmit={submit}><h2>A little about you</h2><label className="field">Full name<input name="full_name" defaultValue={String(profile.data.full_name || '')} required minLength={2} maxLength={100} autoComplete="name" /></label><label className="field">Phone number<input name="phone" type="tel" defaultValue={String(profile.data.phone || '')} autoComplete="tel" /></label><label className="field">Email address<input value={user?.email || ''} readOnly /></label><Notice error={error} success={success} /><button className="btn btn-primary" disabled={busy}>{busy ? 'Saving…' : 'Save profile'}</button></form>}</>;
}
function AccountSettings() {
  const { updatePassword, roles, user } = useAuth(); const [showPassword, setShowPassword] = useState(false); const [error, setError] = useState(''); const [success, setSuccess] = useState(''); const [busy, setBusy] = useState(false);
  async function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; const data = new FormData(form); setError(''); if (data.get('password') !== data.get('confirm')) { setError('The passwords do not match.'); return; } setBusy(true); try { await updatePassword(String(data.get('password'))); setSuccess('Your password has been changed.'); form.reset(); } catch (failure) { setError(messageOf(failure)); } finally { setBusy(false); } }
  return <><form className="card service-form" onSubmit={submit}><h2>Keep your account secure</h2><label className="field">New password<span className="password-field"><input type={showPassword ? 'text' : 'password'} name="password" autoComplete="new-password" minLength={10} maxLength={72} required /><button type="button" className="password-toggle" onClick={() => setShowPassword(!showPassword)} aria-pressed={showPassword} aria-label={showPassword ? 'Hide password' : 'Show password'} title={showPassword ? 'Hide password' : 'Show password'}>{showPassword ? <EyeOff size={18} /> : <Eye size={18} />}</button></span></label><label className="field">Confirm password<input type={showPassword ? 'text' : 'password'} name="confirm" autoComplete="new-password" required /></label><Notice error={error} success={success} /><button className="btn btn-primary" disabled={busy}>{busy ? 'Updating…' : 'Update password'}</button></form><div className="card settings-roles"><h3>Your account access</h3><p className="muted">{user?.email_confirmed_at ? 'Email verified' : 'Email verification pending'}</p><div className="role-list">{roles.map((role) => <span className="badge" key={role}>{titleCase(role)}</span>)}</div><p className="small muted">Operational roles are managed by authorized shelter administrators.</p></div></>;
}
function Addresses() {
  const confirm=useConfirmation();
  const cache = useQueryClient(); const addresses = useQuery({ queryKey: ['addresses'], queryFn: ({signal}) => api<Row[]>('/addresses',{signal}) }); const [edit, setEdit] = useState<Row | null>(null); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  async function save(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const fields = Object.fromEntries(new FormData(event.currentTarget)); setBusy(true); setError(''); try { await api(edit?.id ? `/addresses/${edit.id}` : '/addresses', request(edit?.id ? 'PATCH' : 'POST', { ...fields, latitude: fields.latitude ? Number(fields.latitude) : undefined, longitude: fields.longitude ? Number(fields.longitude) : undefined, is_default: fields.is_default === 'on' })); setEdit(null); await cache.invalidateQueries({ queryKey: ['addresses'] }); } catch (failure) { setError(messageOf(failure)); } finally { setBusy(false); } }
  async function remove(id: unknown) { if (!(await confirm('Remove this saved address?')).confirmed) return; setError(''); try { await api(`/addresses/${id}`, request('DELETE')); await cache.invalidateQueries({ queryKey: ['addresses'] }); } catch (failure) { setError(messageOf(failure)); } }
  return <><button className="btn btn-primary" onClick={() => setEdit({})}><Plus size={17} />Add an address</button><QueryState loading={addresses.isLoading} error={addresses.error} /><Notice error={error} /><div className="address-grid">{addresses.data?.map((address) => <article className="card address-card" key={String(address.id)}><div className="feature-toolbar"><h3><MapPin size={18} />{String(address.label || 'Home')}</h3>{Boolean(address.is_default) && <span className="badge">Default</span>}</div><strong>{String(address.recipient_name)}</strong><p>{String(address.line1)}<br />{[address.barangay, address.city, address.province, address.postal_code].filter(Boolean).join(', ')}</p><p className="muted">{String(address.phone)}</p><div className="table-actions"><button className="text-button" onClick={() => setEdit(address)}>Edit address</button><button className="text-button" onClick={() => remove(address.id)}><Trash2 size={15} />Remove</button></div></article>)}</div>{addresses.data?.length === 0 && <div className="card empty-state"><MapPin size={32} /><h3>A place to send the good stuff.</h3><p>Add your first address to make checkout a little easier.</p></div>}{edit && <div className="modal-backdrop"><form className="card record-modal service-form" onSubmit={save}><div className="feature-toolbar"><h2>{edit.id ? 'Edit address' : 'Add an address'}</h2><button type="button" className="icon-button" onClick={() => setEdit(null)} aria-label="Close address form"><X /></button></div><div className="form-grid">{['label', 'recipient_name', 'phone', 'line1', 'barangay', 'city', 'province', 'postal_code', 'latitude', 'longitude'].map((field) => <label className="field" key={field}>{titleCase(field)}<input name={field} type={field === 'latitude' || field === 'longitude' ? 'number' : field === 'phone' ? 'tel' : 'text'} step="any" min={field === 'latitude' ? -90 : field === 'longitude' ? -180 : undefined} max={field === 'latitude' ? 90 : field === 'longitude' ? 180 : undefined} defaultValue={String(edit[field] ?? (field === 'province' ? 'Bulacan' : ''))} required={['recipient_name', 'phone', 'line1', 'city', 'province', 'latitude', 'longitude'].includes(field)} /></label>)}</div><label className="field">Delivery instructions<textarea name="instructions" defaultValue={String(edit.instructions || '')} /></label><label className="checkbox-label"><input name="is_default" type="checkbox" defaultChecked={Boolean(edit.is_default)} />Set as default address</label><Notice error={error} /><button className="btn btn-primary" disabled={busy}>{busy ? 'Saving…' : 'Save address'}</button></form></div>}</>;
}

type AdminField = { key: string; label?: string; type?: 'text' | 'number' | 'textarea' | 'checkbox' | 'select' | 'json' | 'datetime-local' | 'date'; options?: string[]; required?: boolean };
const adminResources = [
 {key:'security',label:'Security overview',icon:ShieldCheck},{key:'security_events',label:'Security events',icon:ShieldCheck},{key:'security_alerts',label:'Security alerts',icon:ShieldCheck},{key:'critical_approvals',label:'Critical approvals',icon:ShieldCheck},{key:'payments',label:'Payments',icon:ShoppingBag},{key:'refunds',label:'Refund requests',icon:ShoppingBag},{key:'reviews',label:'Customer reviews',icon:Check},
  { key: 'overview', label: 'Overview', icon: LayoutDashboard }, { key: 'products', label: 'Products', icon: Package }, { key: 'categories', label: 'Categories', icon: ShoppingBag }, { key: 'orders', label: 'Orders', icon: ShoppingBag }, { key: 'pets', label: 'Pets', icon: PawPrint }, { key: 'health', label: 'Health records', icon: ClipboardList }, { key: 'adoptions', label: 'Adoption applications', icon: Heart }, { key: 'rescue', label: 'Rescue watch', icon: ShieldCheck }, { key: 'transport', label: 'Transport', icon: Truck }, { key: 'alternatives', label: 'Alternative transport', icon: Truck }, { key: 'zones', label: 'Service zones', icon: MapPin }, { key: 'shelter_location', label: 'Shelter location', icon: MapPin }, { key: 'vehicles', label: 'Vehicles', icon: Truck }, { key: 'drivers', label: 'Drivers', icon: UserRound }, { key: 'donations', label: 'Donations', icon: Heart }, { key: 'volunteers', label: 'Volunteers', icon: Users }, { key: 'users', label: 'People & access', icon: Users }, { key: 'expenses', label: 'Expenses', icon: ClipboardList }, { key: 'audit_logs', label: 'Audit trail', icon: ShieldCheck }, { key: 'contact_messages', label: 'Messages', icon: Bell },
];
